\title{A Positive-Term Series, an Integral Representation, and the Irrationality Engine for the Euler--Mascheroni Constant}
\author{Aristotle}
\date{\today}

\begin{document}
\begin{abstract}
The Euler--Mascheroni constant $\gamma = \lim_{n\to\infty}(H_n - \ln n)$, where $H_n = \sum_{k=1}^n 1/k$, is among the most studied constants in mathematics, yet whether it is rational remains a celebrated open problem. We present a unified, elementary development of $\gamma$ organized around the single positive term $g(k) = 1/k - \ln(1 + 1/k)$. We prove $g(k) > 0$, that the partial sums telescope exactly to the lower approximants $H_n - \ln(n+1)$, and hence $\sum_{k\ge1} g(k) = \gamma$. We exhibit each term as a unit-interval integral $g(k) = \int_k^{k+1}(1/k - 1/y)\,dy$ and assemble the staircase representation $\gamma = \int_1^\infty (1/\lfloor x\rfloor - 1/x)\,dx$. We establish the sharp bound $g(k) < 1/(2k^2)$ and the convergence rate $0 < \gamma - \sum_{k=1}^n g(k) < 1/(2n)$. We locate $\gamma$ as the zeroth Stieltjes constant $\gamma_0$, and we isolate the irrationality engine: a real $x$ is irrational iff there exist integer sequences $(a_n),(b_n)$ with $a_n + b_n x \neq 0$ and $a_n + b_n x \to 0$, reducing the irrationality of $\gamma$ to an explicit Diophantine construction.
\end{abstract}

\maketitle

\section{Introduction}
The Euler--Mascheroni constant
\[
\gamma = \lim_{n\to\infty}\Big(\sum_{k=1}^n \tfrac{1}{k} - \ln n\Big) = 0.57721566490153286\ldots
\]
measures the persistent gap between the harmonic numbers and the natural logarithm. It pervades analysis and number theory, yet two basic questions remain open: is $\gamma$ rational? is it transcendental? We give a self-contained treatment built from a single elementary block, arranged to expose where the irrationality question becomes hard. Our contributions: a positive-term series (\S3), an integral representation (\S4), a sharp convergence rate (\S5), the Stieltjes anchor $\gamma_0 = \gamma$ (\S6), and the irrationality engine with its application to $\gamma$ (\S7).

\section{Preliminaries}
We write $\ln$ for the natural logarithm, $\lfloor x\rfloor$ for the floor, and $H_n = \sum_{k=1}^n 1/k$ (with $H_0 = 0$). Define the standard monotone approximants
\[
L_n = H_n - \ln(n+1) \ (\text{lower}), \qquad U_n = H_n - \ln n \ (\text{upper, } n\ge1),
\]
so that $L_n \uparrow \gamma$ and $U_n \downarrow \gamma$, hence $L_n < \gamma < U_n$ for $n \ge 1$. We repeatedly use the fundamental inequality: for every $x > 0$,
\begin{equation}\tag{$\star$}
\ln(1+x) < x,
\end{equation}
equivalently $\ln t < t-1$ for $t > 1$.

\section{A positive-term series for $\gamma$}
\begin{definition}
For $k \ge 1$ set $g(k) = \dfrac{1}{k} - \ln\!\big(1 + \tfrac{1}{k}\big) = \dfrac{1}{k} - \big(\ln(k+1) - \ln k\big)$, with the convention $g(0) = 0$.
\end{definition}

\begin{theorem}[Positivity]
For every integer $k \ge 1$, $g(k) > 0$.
\end{theorem}
\begin{proof}
Apply $(\star)$ with $x = 1/k > 0$: $\ln(1 + 1/k) < 1/k$, so $g(k) = 1/k - \ln(1+1/k) > 0$.
\end{proof}

\begin{theorem}[Telescoping partial sum]
For every $n \ge 0$, $\displaystyle\sum_{k=1}^n g(k) = H_n - \ln(n+1) = L_n.$
\end{theorem}
\begin{proof}
Write $g(k) = 1/k - (\ln(k+1) - \ln k)$. The first parts sum to $H_n$; the logarithmic parts telescope to $\ln(n+1) - \ln 1 = \ln(n+1)$.
\end{proof}

\begin{theorem}[Series representation]
The series $\sum_{k\ge1} g(k)$ converges and $\displaystyle\sum_{k=1}^\infty g(k) = \gamma$.
\end{theorem}
\begin{proof}
All terms are nonnegative and the partial sums equal $L_n$, bounded above by $\gamma$; hence the series converges, to $\lim_n L_n = \gamma$.
\end{proof}

\begin{corollary}
$L_{n+1} - L_n = g(n+1) > 0$, so $(L_n)$ strictly increases to $\gamma$ from below; in particular $L_n < \gamma$ for all $n$.
\end{corollary}

\section{An integral representation}
\begin{lemma}
For $k \ge 1$ and $x \ge k$, $\ 1/k - 1/x \ge 0$.
\end{lemma}

\begin{theorem}[Integral form of a term]
For every $k \ge 1$, $\displaystyle g(k) = \int_k^{k+1}\Big(\frac1k - \frac1y\Big)\,dy.$
\end{theorem}
\begin{proof}
On $[k,k+1]$ the constant $1/k$ integrates to $1/k$, and $\int_k^{k+1} dy/y = \ln(k+1) - \ln k = \ln(1+1/k)$; subtract.
\end{proof}

\begin{theorem}[Staircase integral representation]
$\displaystyle \gamma = \int_1^\infty\Big(\frac{1}{\lfloor x\rfloor} - \frac1x\Big)\,dx := \lim_{N\to\infty}\int_1^N\Big(\frac{1}{\lfloor x\rfloor} - \frac1x\Big)\,dx.$
\end{theorem}
\begin{proof}
On $[k,k+1)$ we have $\lfloor x\rfloor = k$, so the integrand is $1/k - 1/x$, integrating to $g(k)$. Summing over $1 \le k \le N-1$ gives $\int_1^N = \sum_{k=1}^{N-1} g(k) = L_{N-1} \to \gamma$.
\end{proof}

\section{A sharp convergence rate}
\begin{theorem}[Per-term bound]
For every $k \ge 1$, $\ 0 < g(k) < \dfrac{1}{2k^2}.$
\end{theorem}
\begin{proof}
For $u > 0$, $\ln(1+u) > u - u^2/2$ (the difference has positive derivative $u^2/(1+u)$ and vanishes at $0$). With $u = 1/k$, $g(k) = 1/k - \ln(1+1/k) < 1/k - (1/k - 1/(2k^2)) = 1/(2k^2)$.
\end{proof}

\begin{theorem}[Convergence rate]
For every $n \ge 1$, $\ 0 < \gamma - L_n = \gamma - \displaystyle\sum_{k=1}^n g(k) < \frac{1}{2n}.$
\end{theorem}
\begin{proof}
The remainder is $\sum_{k=n+1}^\infty g(k) < \sum_{k=n+1}^\infty 1/(2k^2) < \tfrac12 \int_n^\infty dx/x^2 = 1/(2n)$.
\end{proof}

\section{The Stieltjes anchor}
\begin{definition}
For $m \ge 0$, $n \ge 1$, set $S_m(n) = \displaystyle\sum_{k=1}^n \frac{(\ln k)^m}{k} - \frac{(\ln n)^{m+1}}{m+1}$; the $m$-th Stieltjes constant is $\gamma_m = \lim_n S_m(n)$.
\end{definition}
These are the Laurent coefficients of the Riemann zeta function at $s=1$:
\[
\zeta(s) = \frac{1}{s-1} + \sum_{m=0}^\infty \frac{(-1)^m}{m!}\,\gamma_m\,(s-1)^m.
\]
\begin{theorem}
$\gamma_0 = \gamma$.
\end{theorem}
\begin{proof}
For $m = 0$, $S_0(n) = \sum_{k=1}^n 1/k - \ln n = H_n - \ln n = U_n \to \gamma$.
\end{proof}

\section{The irrationality engine}
\begin{theorem}[Sufficiency]
If integer sequences $(a_n),(b_n)$ satisfy $a_n + b_n x \neq 0$ for all $n$ and $a_n + b_n x \to 0$, then $x$ is irrational.
\end{theorem}
\begin{proof}
If $x = p/q$ with integer $q \ge 1$, then $a_n + b_n x = (a_n q + b_n p)/q$ has nonzero integer numerator, so $|a_n + b_n x| \ge 1/q > 0$, contradicting convergence to $0$.
\end{proof}

\begin{theorem}[Characterization]
$x \in \R$ is irrational iff there exist integer sequences $(a_n),(b_n)$ with $a_n + b_n x \neq 0$ for all $n$ and $a_n + b_n x \to 0$.
\end{theorem}
\begin{proof}
$(\Leftarrow)$ is the previous theorem. $(\Rightarrow)$: by Dirichlet's approximation theorem an irrational $x$ has infinitely many reduced fractions $p/q$ with $|x - p/q| < 1/q^2$ and unbounded $q$; choose $q_n \ge n+1$ and set $a_n = -p_n$, $b_n = q_n$. Then $|a_n + b_n x| = q_n|x - p_n/q_n| < 1/q_n \le 1/(n+1) \to 0$, and the form is nonzero since $x \neq p_n/q_n$.
\end{proof}

\begin{corollary}
$\gamma$ is irrational iff there exist integer sequences $(a_n),(b_n)$ with $a_n + b_n\gamma \neq 0$ for all $n$ and $a_n + b_n\gamma \to 0$.
\end{corollary}

\noindent\textbf{Where the difficulty lives.} Writing $\gamma = H_n - \ln(n+1) + (\gamma - L_n)$ with $0 < \gamma - L_n < 1/(2n)$, the harmonic part is denominator-friendly: $D_n = \lcm(1,\ldots,n)$ clears $H_n$ and the Prime Number Theorem gives $D_n = e^{n(1+o(1))}$. The obstruction is the additive $\ln(n+1)$, transcendental and not cleared by any common denominator. The linear forms of the corollary must clear $H_n$ \emph{and} approximate $\ln(n+1)$ within the budget $D_n$ can absorb.

\section{Future directions}
\begin{conjecture}[Logarithmic common denominator]
There exist positive integers $b_n$ of at most exponential growth and integers $a_n$ with $b_n\gamma - a_n \neq 0$ yet $b_n\gamma - a_n \to 0$; hence $\gamma$ is irrational. The search should target integer combinations clearing $H_n$ while approximating $\ln(n+1)$ within a factor the exponential denominator absorbs; sharp bounds on $\lcm(1,\ldots,n)$ and on rational approximations to logarithms now let the two error budgets be compared on one scale.
\end{conjecture}
\begin{conjecture}[Irrationality measure]
If such forms exist with $b_n \sim e^{cn}$ and $|b_n\gamma - a_n| \sim e^{-c'n}$, then $\gamma$ has finite irrationality measure $\le 1 + c/c'$. The universal gap $1/q$ upgrades to a two-sided squeeze whose exponents are read off the growth of $\lcm(1,\ldots,n)$ (pinned to $e^{n(1+o(1))}$ by the Prime Number Theorem) and the analytic decay.
\end{conjecture}
\begin{conjecture}[Stieltjes genericity]
Among $\gamma_0 = \gamma, \gamma_1, \gamma_2, \ldots$, all but finitely many are irrational, and no two satisfy a nontrivial rational linear relation. Each $\gamma_m$ uses the same clearing mechanism weighted by $(\ln k)^m$, making simultaneous rationality a far more rigid coincidence; high-precision data reveal no algebraic relations.
\end{conjecture}
\begin{conjecture}[No elementary certificate]
No elementary integral representation of $\gamma$ of the schematic shape above reduces to integer linear forms of subexponential denominator and decay, so any irrationality proof must import genuinely transcendental input.
\end{conjecture}

\section{Conclusion}
From the single term $g(k) = 1/k - \ln(1+1/k)$ we obtained the positive series $\gamma = \sum_{k\ge1} g(k)$ with monotone lower approximants $L_n = H_n - \ln(n+1)$, the staircase integral $\gamma = \int_1^\infty(1/\lfloor x\rfloor - 1/x)\,dx$, and the certified rate $\gamma - L_n < 1/(2n)$ from $g(k) < 1/(2k^2)$. The constant heads the Stieltjes family ($\gamma_0 = \gamma$), and the integer-linear-form criterion reduces its irrationality to an explicit construction, locating the obstruction in the transcendental logarithmic correction.

