function GammaLowerBracket(n):
    H <- 0
    for k from 1 to n:
        H <- H + 1/k
    L <- H - ln(n+1)
    return (L, lower = L, upper = L + 1/(2n))

function StaircasePartial(N):
    total <- 0
    for k from 1 to N-1:
        total <- total + (1/k - ln(1 + 1/k))   # = integral over [k,k+1]
    return total   # -> gamma as N -> infinity

function IrrationalityFormTest(a, b, x, n_max, tol):
    all_nonzero <- true
    values <- []
    for n from 1 to n_max:
        v <- a(n) + b(n)*x
        if |v| < tol: all_nonzero <- false
        append |v| to values
    return { all_nonzero, first = values[0], last = values[-1],
             appears_to_decay = (values[-1] < values[0]) }

function StieltjesConstant(m, n):
    s <- 0
    for k from 1 to n:
        s <- s + (ln k)^m / k
    return s - (ln n)^(m+1)/(m+1)

